function check(input, actual, expected) {
  const [preorder, postorder] = input;
  if (!Array.isArray(actual) || actual.length === 0 || typeof actual[0] !== 'number') return false;
  // Rebuild the returned tree from its level-order form.
  const nodes = [{ val: actual[0], left: null, right: null }];
  let i = 1;
  for (let q = 0; q < nodes.length && i < actual.length; q++) {
    for (const side of ['left', 'right']) {
      if (i < actual.length && actual[i] !== null) {
        if (typeof actual[i] !== 'number') return false;
        const node = { val: actual[i], left: null, right: null };
        nodes[q][side] = node;
        nodes.push(node);
      }
      i++;
    }
  }
  if (actual.slice(i).some(v => v !== null) || nodes.length !== preorder.length) return false;
  // Both of its traversals must reproduce the inputs.
  const pre = [];
  const post = [];
  const walk = (node) => {
    if (!node) return;
    pre.push(node.val);
    walk(node.left);
    walk(node.right);
    post.push(node.val);
  };
  walk(nodes[0]);
  return pre.join() === preorder.join() && post.join() === postorder.join();
}

