function validate([preorder, postorder]) {
  if (!Array.isArray(preorder) || !Array.isArray(postorder)) return 'preorder and postorder must be lists.';
  const n = preorder.length;
  if (n < 1 || n > 30) return 'preorder needs 1 to 30 values.';
  if (postorder.length !== n) return 'postorder must be as long as preorder.';
  for (const list of [preorder, postorder]) {
    if (list.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each value is an integer from 1 to the length.';
    if (new Set(list).size !== n) return 'Values must be distinct.';
  }
  // Rebuild the ranges recursively; every subtree's root must close its postorder range.
  const position = new Map(postorder.map((v, i) => [v, i]));
  const consistent = (preStart, preEnd, postStart) => {
    if (preStart > preEnd) return true;
    const postEnd = postStart + preEnd - preStart;
    if (preorder[preStart] !== postorder[postEnd]) return false;
    if (preStart === preEnd) return true;
    const at = position.get(preorder[preStart + 1]);
    if (at === undefined || at < postStart || at >= postEnd) return false;
    const leftSize = at - postStart + 1;
    return consistent(preStart + 1, preStart + leftSize, postStart) && consistent(preStart + leftSize + 1, preEnd, postStart + leftSize);
  };
  if (!consistent(0, n - 1, 0)) return 'These lists are not the traversals of one binary tree.';
  return null;
}

