function constructFromPrePost(preorder, postorder) {
  const postIndex = new Map();
  for (let i = 0; i < postorder.length; i++) {
    postIndex.set(postorder[i], i);
  }

  function build(preStart, preEnd, postStart) {
    if (preStart > preEnd) {
      return null;
    }
    const root = new TreeNode(preorder[preStart]);
    if (preStart === preEnd) {
      return root;
    }
    const leftRootValue = preorder[preStart + 1];
    const leftSize = postIndex.get(leftRootValue) - postStart + 1;
    root.left = build(preStart + 1, preStart + leftSize, postStart);
    root.right = build(preStart + leftSize + 1, preEnd, postStart + leftSize);
    return root;
  }

  return build(0, preorder.length - 1, 0);
}

