function constructFromPrePost(preorder, postorder) {
  // Stack of the current root-to-node path: a node is finished once it is next in postorder.
  const stack = [new TreeNode(preorder[0])];
  let done = 0;
  for (let k = 1; k < preorder.length; k++) {
    const node = new TreeNode(preorder[k]);
    while (stack[stack.length - 1].val === postorder[done]) {
      stack.pop();
      done++;
    }
    const parent = stack[stack.length - 1];
    if (!parent.left) parent.left = node;
    else parent.right = node;
    stack.push(node);
  }
  return stack[0];
}

