function generate(rand, size) {
  const n = size === 'large' ? 30 : 1 + Math.floor(rand() * 7);
  // Random shape: split the remaining nodes between the two subtrees, sometimes all to one side.
  const shape = (count) => {
    if (count === 0) return null;
    const rest = count - 1;
    const pick = rand();
    const leftCount = pick < 0.2 ? rest : pick < 0.4 ? 0 : Math.floor(rand() * (rest + 1));
    return { left: shape(leftCount), right: shape(rest - leftCount) };
  };
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const preorder = [];
  const postorder = [];
  let next = 0;
  const walk = (node) => {
    if (!node) return;
    const value = values[next++];
    preorder.push(value);
    walk(node.left);
    walk(node.right);
    postorder.push(value);
  };
  walk(shape(n));
  return [preorder, postorder];
}
